// GOOGLE DRIVE
// =====================================================
const DRIVE_SCOPE = "https://www.googleapis.com/auth/drive";
let googleAccessToken = null;
let tokenClient = null;

function googleClientId(){
  return (appSettings.googleClientId || window.RAPPORTINO_GOOGLE_CLIENT_ID || "").trim();
}

function initGoogleDrive(){
  const btn = $("googleLoginBtn");

  if(!googleClientId()){
    $("driveStatusTitle").textContent = "Google Drive da configurare";
    $("driveStatusText").textContent = "Apri Impostazioni e inserisci il Client ID Google.";
    btn.disabled = true;
    return;
  }

  const waitForGoogle = () => {
    if(window.google?.accounts?.oauth2){
      tokenClient = google.accounts.oauth2.initTokenClient({
        client_id: googleClientId(),
        scope: DRIVE_SCOPE,
        callback: tokenResponse => {
          if(tokenResponse?.error){
            setDriveDisconnected(`Errore Google: ${tokenResponse.error}`);
            return;
          }
          googleAccessToken = tokenResponse.access_token;
          $("driveStatusTitle").textContent = "Google Drive collegato";
          $("driveStatusText").textContent = "Puoi salvare e riaprire i dati del rapportino. Il PDF si genera quando serve.";
          $("driveControls").classList.remove("hidden");
          $("googleLoginBtn").classList.add("hidden");
          syncDriveButtons();
        }
      });
      btn.disabled = false;
    } else {
      setTimeout(waitForGoogle, 250);
    }
  };
  waitForGoogle();
}

function requestGoogleToken(){
  if(!tokenClient){
    $("settingsBtn").click();
    $("settingsStatus").textContent="Configura il collegamento Google, salva le impostazioni e accedi per salvare il rapportino.";
    return;
  }
  tokenClient.requestAccessToken({prompt: googleAccessToken ? "" : "consent"});
}

function setDriveDisconnected(message="Non collegato a Google Drive."){
  googleAccessToken = null;
  $("driveStatusTitle").textContent = "Non collegato";
  $("driveStatusText").textContent = message;
  $("driveControls").classList.add("hidden");
  $("googleLoginBtn").classList.remove("hidden");
  syncDriveButtons();
}

function syncDriveButtons(){
  if($("saveDriveBtn")){
    $("saveDriveBtn").disabled = savingDrive;
  }
}

async function driveFetch(url, options={}){
  if(!googleAccessToken) throw new Error("Google Drive non collegato");
  const headers = new Headers(options.headers || {});
  headers.set("Authorization", `Bearer ${googleAccessToken}`);
  const res = await fetch(url, {...options, headers});

  if(res.status === 401){
    setDriveDisconnected("Accesso Google scaduto. Accedi di nuovo.");
    throw new Error("Sessione Google scaduta");
  }
  return res;
}

function driveEscapeQuery(s){
  return String(s).replace(/\\/g,"\\\\").replace(/'/g,"\\'");
}

async function findFolder(name, parentId=null){
  let q = `mimeType='application/vnd.google-apps.folder' and trashed=false and name='${driveEscapeQuery(name)}'`;
  if(parentId) q += ` and '${parentId}' in parents`;

  const url = "https://www.googleapis.com/drive/v3/files?" + new URLSearchParams({
    q,
    spaces:"drive",
    fields:"files(id,name,parents)",
    pageSize:"20"
  });

  const res = await driveFetch(url);
  if(!res.ok) throw new Error(`Ricerca cartella Drive fallita (${res.status})`);
  const data = await res.json();
  return data.files?.[0] || null;
}

async function createFolder(name, parentId=null){
  const metadata = {
    name,
    mimeType:"application/vnd.google-apps.folder"
  };
  if(parentId) metadata.parents=[parentId];

  const res = await driveFetch("https://www.googleapis.com/drive/v3/files?fields=id,name,parents", {
    method:"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify(metadata)
  });
  if(!res.ok) throw new Error(`Creazione cartella Drive fallita (${res.status})`);
  return await res.json();
}

async function getOrCreateFolder(name, parentId=null){
  const existing = await findFolder(name,parentId);
  return existing || await createFolder(name,parentId);
}

async function ensureReportFolder(){
  if(appSettings.driveFolderId){
    const res=await driveFetch("https://www.googleapis.com/drive/v3/files/"+encodeURIComponent(appSettings.driveFolderId)+"?fields=id,name,mimeType,trashed,capabilities(canAddChildren)");
    if(!res.ok)throw new Error("Cartella non accessibile: controlla link e account Google.");
    const folder=await res.json();
    if(folder.trashed||folder.mimeType!=="application/vnd.google-apps.folder"||folder.capabilities?.canAddChildren===false)throw new Error("La cartella non è disponibile per il salvataggio.");
    return folder;
  }
  const folder=await getOrCreateFolder("Rapportini","root");
  appSettings.driveFolderId=folder.id;
  localStorage.setItem(SETTINGS_KEY,JSON.stringify(appSettings));
  return folder;
}
async function findReportFile(parentId,name,key,type){
  const q=`trashed=false and '${driveEscapeQuery(parentId)}' in parents and (name='${driveEscapeQuery(name)}' or (appProperties has { key='reportKey' and value='${driveEscapeQuery(key)}' } and appProperties has { key='type' and value='${type}' }))`;
  const res=await driveFetch("https://www.googleapis.com/drive/v3/files?"+new URLSearchParams({q,fields:"files(id,name)",pageSize:"100"}));
  if(!res.ok)throw new Error("Impossibile controllare i rapportini già presenti.");
  const files=(await res.json()).files||[];
  if(files.length>1)throw new Error("Sono presenti più copie dello stesso rapportino nella cartella: riordinale prima di salvare.");
  return files[0]?.id||null;
}
async function uploadMultipartFile({name,mimeType,parentId,blob,appProperties={},fileId=null}){
  const boundary = "-------rapportino_" + Math.random().toString(36).slice(2);
  const metadata = {name,mimeType,appProperties};
  if(!fileId) metadata.parents=[parentId];

  const prefix =
    `--${boundary}\r\n` +
    `Content-Type: application/json; charset=UTF-8\r\n\r\n` +
    `${JSON.stringify(metadata)}\r\n` +
    `--${boundary}\r\n` +
    `Content-Type: ${mimeType}\r\n\r\n`;

  const suffix = `\r\n--${boundary}--`;

  const body = new Blob([prefix, blob, suffix]);

  const res = await driveFetch(
    "https://www.googleapis.com/upload/drive/v3/files"+(fileId?"/"+encodeURIComponent(fileId):"")+"?uploadType=multipart&fields=id,name,webViewLink,mimeType,createdTime",
    {
      method:fileId?"PATCH":"POST",
      headers:{"Content-Type":`multipart/related; boundary=${boundary}`},
      body
    }
  );
  if(!res.ok){
    const msg = await res.text();
    throw new Error(`Upload Drive fallito (${res.status}): ${msg}`);
  }
  return await res.json();
}

function currentReportData(){
  return {
    schemaVersion: 1,
    reportId: reportKey(),
    clientName: $("clientName").value.trim(),
    date: $("date").value,
    technicians: technicians.map(t => JSON.parse(JSON.stringify(t))),
    workDone: $("workDone").value,
    materialsUsed: $("materialsUsed").value,
    materialsRepaired: $("materialsRepaired").value,
    signatureDataUrl,
    savedAt: new Date().toISOString()
  };
}

function jsonFilename(){return filenameForReport().replace(/\.pdf$/, ".json");}

async function saveCurrentReportToDrive(){
  if(savingDrive)return;
  if(!$("clientName").value.trim()){alert("Inserisci il nome del locale.");return;}

  if(!googleAccessToken){
    requestGoogleToken();
    return;
  }

  const btn = $("saveDriveBtn");
  const old = btn.textContent;
  btn.disabled = true;
  btn.textContent = "Salvataggio...";
  savingDrive = true;

  try{
    const folder = await ensureReportFolder();
    const data = currentReportData();

    const jsonBlob = new Blob([JSON.stringify(data,null,2)], {type:"application/json"});
    const key=reportKey();
    const jsonId=await findReportFile(folder.id,jsonFilename(),key,"data");

    await uploadMultipartFile({
      name: jsonFilename(),
      mimeType:"application/json",
      parentId:folder.id,
      blob:jsonBlob,
      fileId:jsonId,
      appProperties:{
        reportKey:key,
        rapportino:"1",
        type:"data",
        reportDate:data.date,
        client:data.clientName
      }
    });

    $("driveStatusTitle").textContent = "Salvato su Google Drive";
    $("driveStatusText").textContent = `${folder.name} / ${jsonFilename()}`;
  }catch(err){
    console.error(err);
    alert("Errore durante il salvataggio su Google Drive:\n" + err.message);
  }finally{
    savingDrive = false;
    btn.textContent = old;
    syncDriveButtons();
  }
}

async function listDriveReports(){
  $("archiveList").innerHTML = "";
  $("archiveStatus").textContent = "Caricamento archivio...";

  try{
  const folder=await ensureReportFolder();
  const q = "'"+driveEscapeQuery(folder.id)+"' in parents and trashed=false and appProperties has { key='rapportino' and value='1' } and appProperties has { key='type' and value='data' }";
  const url = "https://www.googleapis.com/drive/v3/files?" + new URLSearchParams({
    q,
    spaces:"drive",
    orderBy:"createdTime desc",
    pageSize:"100",
    fields:"nextPageToken,files(id,name,createdTime,modifiedTime,parents,appProperties,webViewLink,mimeType)"
  });

    let files=[],pageToken="";
    do {
    const res = await driveFetch(url+(pageToken?"&pageToken="+encodeURIComponent(pageToken):""));
    if(!res.ok) throw new Error(`Archivio Drive non disponibile (${res.status})`);
    const data = await res.json();
    files.push(...(data.files||[]));
    pageToken=data.nextPageToken||"";
    } while(pageToken);

    $("archiveStatus").textContent = files.length ? `${files.length} rapportini trovati` : "Nessun rapportino salvato su Drive.";
    files.forEach(file => renderArchiveItem(file));
  }catch(err){
    $("archiveStatus").textContent = err.message;
  }
}

function renderArchiveItem(file){
  const wrap = $("archiveList");
  const item = document.createElement("div");
  item.className = "archive-item";

  const client = file.appProperties?.client || "Senza cliente";
  const date = file.appProperties?.reportDate || "";
  const created = file.createdTime ? new Date(file.createdTime).toLocaleString("it-IT") : "";

  item.innerHTML = `
    <div class="archive-item-head">
      <div>
        <div class="archive-title">${escapeHtml(client)}</div>
        <div class="archive-meta">${escapeHtml(date)}${created ? " • salvato "+escapeHtml(created) : ""}</div>
      </div>
    </div>
    <div class="archive-actions">
      <button class="archive-open">Apri</button>
      <button class="archive-duplicate">Duplica</button>
    </div>
  `;

  item.querySelector(".archive-open").onclick = async () => {
    await loadReportFromDrive(file.id, false);
  };
  item.querySelector(".archive-duplicate").onclick = async () => {
    await loadReportFromDrive(file.id, true);
  };

  wrap.appendChild(item);
}

async function loadReportFromDrive(fileId, duplicate=false){
  try{
    const res = await driveFetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media`);
    if(!res.ok) throw new Error(`Apertura rapportino fallita (${res.status})`);
    const d = await res.json();

    $("clientName").value = d.clientName || "";
    $("date").value = d.date || todayISO();
    technicians = Array.isArray(d.technicians) ? d.technicians : [];
    $("workDone").value = d.workDone || "";
    $("materialsUsed").value = d.materialsUsed || "";
    $("materialsRepaired").value = d.materialsRepaired || "";
    signatureDataUrl = d.signatureDataUrl || null;

    currentPdfBlob = null;
    if(currentPdfUrl) URL.revokeObjectURL(currentPdfUrl);
    currentPdfUrl = null;

    updateSignatureUi();
    renderTechnicians();
    persistDraft();
    syncButtons();
    syncDriveButtons();

    hideModal("archiveModal");

    if(duplicate){
      $("driveStatusTitle").textContent = "Rapportino duplicato";
      $("driveStatusText").textContent = "Cambia data o nome del locale e salva per creare un nuovo rapportino.";
    }else{
      $("driveStatusTitle").textContent = "Rapportino aperto da Drive";
      $("driveStatusText").textContent = "Puoi correggere i dati e salvare il rapportino. Genera il PDF quando serve.";
    }
    window.scrollTo({top:0,behavior:"smooth"});
  }catch(err){
    alert(err.message);
  }
}

function googleLogout(){
  if(googleAccessToken && window.google?.accounts?.oauth2){
    google.accounts.oauth2.revoke(googleAccessToken, ()=>{});
  }
  setDriveDisconnected();
}

