$("closeSettingsBtn").onclick=()=>hideModal("settingsModal");
$("resetLogoBtn").onclick=()=>{pendingLogo=null;$("settingsLogoPreview").src="assets/logo_esx.png";};
$("settingsLogoFile").onchange=async e=>{
  const file=e.target.files[0];if(!file)return;
  try{
    if(file.size>10*1024*1024)throw new Error("Scegli un’immagine di massimo 10 MB.");
    const bitmap=await createImageBitmap(file);
    const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));
    const canvas=document.createElement("canvas");canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);
    const ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
    pendingLogo=canvas.toDataURL("image/png");$("settingsLogoPreview").src=pendingLogo;$("settingsStatus").textContent="Logo pronto. Premi Salva per applicarlo.";
  }catch(err){$("settingsStatus").textContent="Immagine non caricata: "+err.message;}
  e.target.value="";
};
$("saveSettingsBtn").onclick=()=>{
  try{
    const driveFolderId=folderIdFromInput($("settingsDriveFolder").value);
    const googleClientId=$("settingsGoogleClient").value.trim();
    if(googleClientId&&!googleClientId.endsWith(".apps.googleusercontent.com"))throw new Error("Client ID Google non valido.");
    const next={logo:pendingLogo,driveFolderId,googleClientId};
    localStorage.setItem(SETTINGS_KEY,JSON.stringify(next));
    const authChanged=googleClientId!==window.RAPPORTINO_GOOGLE_CLIENT_ID&&googleClientId!==appSettings.googleClientId;
    appSettings=next;pdfLogoImage=null;applyAppLogo();
    if(authChanged){setDriveDisconnected();tokenClient=null;initGoogleDrive();}
    hideModal("settingsModal");
  }catch(err){$("settingsStatus").textContent="Impostazioni non salvate: "+err.message;}
};
